import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const p=JSON.parse('{"title":"Exercise","description":"","frontmatter":{},"headers":[],"relativePath":"demos/EXERCISE.md","filePath":"demos/EXERCISE.md"}'),n={name:"demos/EXERCISE.md"};function l(o,e,i,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="exercise" tabindex="-1">Exercise <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;Exercise&quot;">​</a></h1><p>Exercises: the simplest sets, to start with.</p><ul><li><a href="#accents">Accents</a>: <code>26_accents.yml</code></li><li><a href="#draws">Draws</a>: <code>28_draws.yml</code></li><li><a href="#guitarify">Guitarify</a>: <code>21_guitarify.yml</code></li><li><a href="#hello_world">Hello World</a>: <code>01_hello_world.yml</code></li><li><a href="#pattern_lists">Pattern Lists</a>: <code>27_pattern_lists.yml</code></li><li><a href="#scale">Scales</a>: <code>04_scale.yml</code></li></ul><p><a id="accents"></a></p><h2 id="accents-26-accents-yml" tabindex="-1">Accents: <code>26_accents.yml</code> <a class="header-anchor" href="#accents-26-accents-yml" aria-label="Permalink to &quot;Accents: `26_accents.yml`&quot;">​</a></h2><p>A funk groove in E minor with no velocity typed on any step. Each part plays at the Default velocity of its track, and a step whose Accent switch is on plays louder by the track&#39;s Accent. The first scene plays four bars with every switch off, so the groove sounds flat. The scenes after it switch accents on a part at a time: the hats on the beat, then off the beat, then a snare whose quiet ghost notes sit under an accented backbeat, then the bass and the keys, then hats accented in threes across the beat. The last scene plays the first again, to hear what the switches did.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/26_accents.yml" target="_blank" rel="noreferrer"><code>examples/learning/26_accents.yml</code></a> · E minor · 100 BPM · 2:19 · 7 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">accents</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../TRACKS">✓</a></td></tr></tbody></table><p><a id="draws"></a></p><h2 id="draws-28-draws-yml" tabindex="-1">Draws: <code>28_draws.yml</code> <a class="header-anchor" href="#draws-28-draws-yml" aria-label="Permalink to &quot;Draws: `28_draws.yml`&quot;">​</a></h2><p>Draws in eleven scenes, every note written as the same C in a chromatic scale, so that everything that moves is a draw. A count-in plays C, C#, D and D# from a draw that moves forward. Four scenes deal twelve-tone rows from a serial draw, which plays every pitch of the octave once before any comes again: plainly, passed between two instruments, with rests and leaps, and in pairs. Four scenes over a bass add two draws on alternate steps, add them together, pull one against the other, and add all three. The last two scenes gate notes by draws: a melody that grows as a draw counts the bars, and a bell whose rhythm comes from a draw that its own condition redraws.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/28_draws.yml" target="_blank" rel="noreferrer"><code>examples/learning/28_draws.yml</code></a> · C chromatic · 108 BPM · 2:58 · 11 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">draws</th><th style="text-align:center;">conditional execution</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../DRAWS">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#stop-when-restart-when-and-mute-when">✓</a></td></tr></tbody></table><p><a id="guitarify"></a></p><h2 id="guitarify-21-guitarify-yml" tabindex="-1">Guitarify: <code>21_guitarify.yml</code> <a class="header-anchor" href="#guitarify-21-guitarify-yml" aria-label="Permalink to &quot;Guitarify: `21_guitarify.yml`&quot;">​</a></h2><p>A tour of guitar playing in twenty-one short scenes, each a way a guitar is played, on seven General MIDI guitars and nothing else: chords as written strummed in Strum mode, a country bass note and strum, picking with thumb and fingers, bluegrass crosspicking, jazz comping, a blues in open G, power chords, a surf tremolo, the folk strum, funk scratching, a singer&#39;s rolled chords, metal gallops and a twelve bar shuffle. Every pattern is only a row of chords or low notes, and the Guitarify generator of each scene does the playing, so the demo shows what its Strum mode and its Shape and Strokes halves do to the same kind of pattern.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/21_guitarify.yml" target="_blank" rel="noreferrer"><code>examples/learning/21_guitarify.yml</code></a> · G major · 104 BPM · 3:19 · 21 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th><th style="text-align:center;">strum</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td></tr></tbody></table><p><a id="hello_world"></a></p><h2 id="hello-world-01-hello-world-yml" tabindex="-1">Hello World: <code>01_hello_world.yml</code> <a class="header-anchor" href="#hello-world-01-hello-world-yml" aria-label="Permalink to &quot;Hello World: `01_hello_world.yml`&quot;">​</a></h2><p>The smallest set there is: a C major scale up in the first scene, down in the second, and up again in the third while a second track holds a C chord for a quarter note, every note a sixteenth. Three seconds long. Open it to see what a pattern, a track and a scene are, play it first when setting up real-time MIDI (<code>docs/MIDI_SETUP.md</code>), and record it first (<code>docs/RECORDING.md</code>).</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/01_hello_world.yml" target="_blank" rel="noreferrer"><code>examples/learning/01_hello_world.yml</code></a> · C major · 120 BPM · 0:03 · 3 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td></tr></tbody></table><p><a id="pattern_lists"></a></p><h2 id="pattern-lists-27-pattern-lists-yml" tabindex="-1">Pattern Lists: <code>27_pattern_lists.yml</code> <a class="header-anchor" href="#pattern-lists-27-pattern-lists-yml" aria-label="Permalink to &quot;Pattern Lists: `27_pattern_lists.yml`&quot;">​</a></h2><p>A hard rock riff in E minor made of four patterns of one bar each: the main figure, an answer, a run up and a stop. Every clip of the riff plays a list of those patterns, as <a href="./../CLIPS#pattern-lists">Pattern Lists</a> describes, and every section of the song is the same four bars in another order. The first scene plays the four bars once. The verse and the chorus list them two ways, with the bass listing bars of its own and the drums playing three bars of the beat and a fill. The scenes after show Pattern order: alternate, pendulum, and first, then random. The seventh scene sets Step direction, which plays the steps inside each pattern backward while the patterns keep their order.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/27_pattern_lists.yml" target="_blank" rel="noreferrer"><code>examples/learning/27_pattern_lists.yml</code></a> · E minor · 120 BPM · 2:24 · 8 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">guitarify</th><th style="text-align:center;">directions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#play-directions">✓</a></td></tr></tbody></table><p><a id="scale"></a></p><h2 id="scales-04-scale-yml" tabindex="-1">Scales: <code>04_scale.yml</code> <a class="header-anchor" href="#scales-04-scale-yml" aria-label="Permalink to &quot;Scales: `04_scale.yml`&quot;">​</a></h2><p>Every scale llamatron knows, each run up an octave and back down from D, one scene per scale, in the order of the scale picker. Use it to preview a scale before choosing one. The demo shows that a scene can set its own scale, and that a degree past the top of a scale wraps up an octave.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/04_scale.yml" target="_blank" rel="noreferrer"><code>examples/learning/04_scale.yml</code></a> · D major · 120 BPM · 3:01 · 47 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">key changes</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td></tr></tbody></table>',33)])])}const y=t(n,[["render",l]]);export{p as __pageData,y as default};
